import assert from "node:assert/strict";
import test from "node:test";
import { left_pad } from "./impl.js";

// Expectations follow SPEC.md: code points, no normalization, no truncation.
const cases = [
  { name: "pads a supplementary code point", input: ["😊", 3], expected: "  😊" },
  { name: "pads multiple supplementary code points", input: ["😊😊", 3], expected: " 😊😊" },
  { name: "counts a combining mark separately without normalization", input: ["e\u0301", 3], expected: " e\u0301" },
  { name: "counts code points within a joined emoji separately", input: ["👩\u200d💻", 4], expected: " 👩\u200d💻" },
  { name: "pads ASCII", input: ["x", 3], expected: "  x" },
  { name: "pads an empty string", input: ["", 3], expected: "   " },
  { name: "preserves a string at the target length", input: ["😊", 1], expected: "😊" },
  { name: "never truncates", input: ["😊x", 1], expected: "😊x" },
  { name: "preserves a string for a zero target", input: ["😊", 0], expected: "😊" },
];

for (const { name, input, expected } of cases) {
  test(name, () => {
    assert.equal(left_pad(...input), expected);
  });
}

